INSERT INTO blog_edicao_posts (id, titulo, categoria, resumo, autor, tempo_leitura_min, data_publicacao, imagem_url, conteudo_md) VALUES
('art-clas-01', 'Os Miseráveis de Victor Hugo: A Injustiça Penal e o Caso Jean Valjean', 'Clássicos', 'Analise o clássico de Victor Hugo sob a ótica do Direito Penal e das penas desproporcionais: o confronto entre Jean Valjean e o inspetor Javert.', 'Redação Estudos Jurídicos', 10, '2026-08-05', 'https://dnjrgpldcwcpoywamorr.supabase.co/storage/v1/object/public/blog-capas/classicos.png', $md$Publicado em 1862 por **Victor Hugo**, o clássico **Os Miseráveis** oferece uma crítica cortante ao sistema legal e penitenciário da França do século XIX.

---

### ⚖️ O Julgamento de Jean Valjean e a Legalidade Cega de Javert

- **A Desproporcionalidade da Pena**: Jean Valjean é condenado a 5 anos de galés pelo furto de um pão para alimentar a família faminta (com aumentos sucessivos por tentativas de fuga até 19 anos).
- **Javert e o Legalismo Estrito**: O inspetor Javert encarna o punitivismo cego que reduz a justiça à aplicação mecânica da lei, incapaz de enxergar a redenção humana.$md$),
('art-clas-02', 'O Sol É para Todos (To Kill a Mockingbird): A Defesa da Dignidade Humana', 'Clássicos', 'As lições de ética profissional e coragem do advogado Atticus Finch no combate ao racismo institucional e preconceito no júri popular.', 'Redação Estudos Jurídicos', 9, '2026-08-04', 'https://dnjrgpldcwcpoywamorr.supabase.co/storage/v1/object/public/blog-capas/classicos.png', $md$Vencedor do Prêmio Pulitzer em 1960, **O Sol É para Todos**, de Harper Lee, é uma leitura indispensável para qualquer estudante de Direito.

---

> 💡 **O Exemplo de Atticus Finch**:
> O advogado Atticus Finch assume a defesa de Tom Robinson, um homem negro injustamente acusado de um crime em pleno Alabama da década de 1930. Ele demonstra que o sacerdócio da advocacia exige defender os direitos fundamentais mesmo quando a opinião pública é abertamente hostil.$md$),
('art-clas-03', 'A Luta pelo Direito de Rudolf von Ihering: A Paz Jurídica Exige Combate', 'Clássicos', 'Por que o jurista alemão defende que o Direito não é mero conceito teórico, mas uma conquista obtida através da resistência ativa e diária.', 'Redação Estudos Jurídicos', 10, '2026-08-03', 'https://dnjrgpldcwcpoywamorr.supabase.co/storage/v1/object/public/blog-capas/classicos.png', $md$Em **A Luta pelo Direito (1872)**, Rudolf von Ihering sustenta que todas as grandes conquistas do ordenamento jurídico (como o fim da escravidão ou a liberdade de expressão) custaram batalhas intensas contra o arbítrio.

---

> 📜 **Frase Célere de Ihering**:
> *"O fim do Direito é a paz; o meio de atingi-lo é a luta."*$md$),
('art-clas-04', 'Dos Delitos e das Penas de Cesare Beccaria: A Origem do Direito Penal Moderno', 'Clássicos', 'A obra de 1764 que aboliu a tortura, humanizou as penas e estabeleceu a anterioridade e proporcionalidade das sanções penais.', 'Redação Estudos Jurídicos', 10, '2026-08-02', 'https://dnjrgpldcwcpoywamorr.supabase.co/storage/v1/object/public/blog-capas/classicos.png', $md$Publicado anonimamente em 1764 pelo jovem marquês italiano **Cesare Beccaria**, o livro **Dos Delitos e das Penas** é a certidão de nascimento do Direito Penal Garantista moderno.

---

### 🛡️ Princípios Fundamentais Estabelecidos por Beccaria

- **Fim das Penas Cruéis e da Tortura**: A tortura como meio de prova é ilógica e bárbara.
- **Anterioridade e Legalidade**: Somente leis escritas pelo legislador podem definir crimes e penas.
- **Proporcionalidade**: A pena deve ser estritamente proporcional ao dano causado à sociedade.$md$),
('art-clas-05', 'O Processo de Franz Kafka: A Burocracia Asfixiante e o Devido Processo Legal', 'Clássicos', 'O drama de Josef K.: uma alegoria trágica sobre a violação da ampla defesa, ausência de acusação formal e opacidade do sistema judicial.', 'Redação Estudos Jurídicos', 9, '2026-08-01', 'https://dnjrgpldcwcpoywamorr.supabase.co/storage/v1/object/public/blog-capas/classicos.png', $md$No romance **O Processo (1925)**, Josef K. é preso de surpresa em sua casa sem saber por qual crime é acusado ou por qual autoridade foi instaurado o procedimento.

---

> 💡 **A Importância do Devido Processo Legal (Art. 5º, LIV da CF/88)**:
> O pesadelo Kafkaiano ilustra o valor inestimável dos direitos constitucionais ao contraditório, ampla defesa e ciência formal dos atos acusatórios.$md$);